/* بيانات باب maal: تُحمَّل عند أول فتح للقسم */
window.MAAL = {"ch":[{"id":"haqiqa","t":"حقيقة المال في ميزان القرآن","d":"كيف تصف الآيات المال: زينة ومتاعاً وفتنة وأمانة مستخلَفاً فيها، وما الذي يقرّب إلى الله حقاً."},{"id":"kasb","t":"طلب الرزق والكسب الحلال","d":"الأمر بالسعي في الأرض وابتغاء فضل الله، وأن يكون الأكل حلالاً طيباً."},{"id":"tijara","t":"التجارة مع الله: الربح والخسارة","d":"استعمل القرآن لغة التجارة والبيع والشراء ليبيّن ربح الإيمان وخسارة الضلال."},{"id":"mizan","t":"الأمانة والعدل في الكيل والميزان","d":"وعيد المطففين، ودعوة شعيب قومه إلى القسط في المكيال والميزان، والميزان الذي وضعه الله في الكون."},{"id":"infaq","t":"الإنفاق والعطاء: المال في خدمة المجتمع","d":"آيات الصدقة والزكاة والقرض الحسن وحقّ السائل والمحروم، وتوزيع المال حتى لا يكون دُولةً بين الأغنياء."},{"id":"itidal","t":"الاعتدال بين البخل والإسراف","d":"الوسط الذي رسمه القرآن للمنفق، وذمّ البخل والتبذير والإسراف."},{"id":"iktinaz","t":"الكنز والتكاثر وحب جمع المال","d":"التحذير من اكتناز المال وعدّه والتفاخر بكثرته وأكل التراث وحبّ المال حبّاً جمّاً."},{"id":"rizq","t":"الرزق والغنى والفقر","d":"ما قرّرته الآيات في أن الرزق بيد الله، وحكمة البسط والتقدير، ووعد الله، ووعد الشيطان بالفقر."},{"id":"namadhij","t":"نماذج قرآنية في فتنة المال","d":"مثالان ضربهما القرآن لمن طغى بماله، ليُعتبر بهما."}],"i":[{"id":"zina","ch":"haqiqa","t":"المال زينة الحياة الدنيا والباقيات الصالحات خير","r":[18,46,46],"n":"تجعل الآية المال والبنين زينة الحياة الدنيا، وتقابلها بالباقيات الصالحات التي هي خير عند الله ثواباً وخير أملاً.","wd":0,"q":{"w":"السعدي","bk":"saadi","s":18,"ay":46,"x":"ولهذا أخبر تعالى أنَّ المال والبنين {زينةُ الحياة الدُّنيا}؛ أي: ليس وراء ذلك شيءٌ، وأنَّ الذي يبقى للإنسان وينفعُهُ ويسرُّه الباقيات الصالحات، وهذا يَشْمَلُ جميع الطاعات الواجبات والمستحبَّة من حقوق الله وحقوق عبادِهِ من صلاةٍ وزكاةٍ وصدقةٍ وحجٍّ وعمرةٍ وتسبيح وتحميدٍ وتهليل [وتكبير] وقراءةٍ وطلب علم نافع وأمرٍ بمعروفٍ ونهي عن منكرٍ وصلة رحم وبرِّ والدين وقيام بحقِّ الزوجات والمماليك والبهائم وجميع وجوه الإحسان إلى الخلق، كلُّ هذا من الباقيات الصالحات؛ فهذه خيرٌ عند الله ثواباً وخيرٌ أملاً …","en":"Hence Allah informed us that wealth and children are \"the adornment of worldly life\", meaning there is nothing beyond that; and that what remains for a person, benefits him and gladdens him is the lasting good deeds. This includes all obligatory and recommended acts of obedience, of the rights of Allah and the rights of His servants: prayer, zakat, charity, Hajj and Umrah, glorification, praise, declaring His oneness, magnification, recitation, seeking beneficial knowledge, enjoining good and forbidding evil, joining kinship, dutifulness to parents, fulfilling the rights of wives, dependants and animals, and all forms of kindness to creation; all of this is among the lasting good deeds, and these \"are better with Allah in reward and better in hope\" …"}},{"id":"shahwat","ch":"haqiqa","t":"حب الشهوات والقناطير المقنطرة من الذهب والفضة","r":[3,14,15],"n":"تذكر الآية أن حب الشهوات زُيِّن للناس ومنها القناطير المقنطرة من الذهب والفضة، وتقول إنها متاع الحياة الدنيا وإن عند الله حسن المآب.","wd":0,"q":{"w":"السعدي","bk":"saadi","s":3,"ay":14,"x":"أخبر تعالى في هاتين الآيتين عن حالة الناس في إيثار الدنيا على الآخرة، وبين التفاوت العظيم والفرق الجسيم بين الدارين، فأخبر أن الناس زينت لهم هذه الأمور فرمقوها بالأبصار، واستحلوها بالقلوب، وعكفت على لذاتها النفوس، كل طائفة من الناس تميل إلى نوع من هذه الأنواع، قد جعلوها هي أكبر همهم ومبلغ علمهم، وهي مع هذا متاع قليل مُنْقَضٍ في مدة يسيرة، فهذا {متاع الحياة الدنيا والله عنده حسن المآب}.","en":"In these two verses He informed us of people's state in preferring this world to the Hereafter, and made clear the great difference and wide gap between the two abodes. He told us that these things were made attractive to people, so they gazed at them with their eyes, found them lawful in their hearts and clung to their pleasures with their souls; each group of people inclines to one kind of these things and has made it its greatest concern and the limit of its knowledge, while it is, for all that, scanty enjoyment that ends in a short time: this is \"the enjoyment of worldly life, while Allah has with Him the best return\"."}},{"id":"istikhlaf","ch":"haqiqa","t":"المال مستخلَف فيه: أنفقوا مما جعلكم مستخلفين فيه","r":[57,7,7],"n":"تأمر الآية بالإيمان وبالإنفاق مما جعل الله الناس مستخلفين فيه، وتعد الذين آمنوا وأنفقوا بأجر كبير.","wd":0,"q":{"w":"السعدي","bk":"saadi","s":57,"ay":7,"x":"يأمر تعالى عبادَه بالإيمان به، وبرسوله وبما جاء به، وبالنفقة في سبيله من الأموال التي جعلها الله في أيديهم واستخْلَفَهم عليها؛ لينظر كيف يعملونَ.","en":"He commands His servants to believe in Him, in His Messenger and in what he brought, and to spend in His cause from the wealth that Allah placed in their hands and made them successors over, so that He may see how they act."}},{"id":"zulfa","ch":"haqiqa","t":"ما أموالكم ولا أولادكم بالتي تقربكم عندنا زلفى","r":[34,37,37],"n":"تنفي الآية أن تكون الأموال والأولاد هي التي تقرّب إلى الله، وتجعل القربى للإيمان والعمل الصالح مع تضعيف الجزاء.","wd":0,"q":{"w":"السعدي","bk":"saadi","s":34,"ay":37,"x":"وليست الأموال والأولاد {بالتي} تقرب إلى الله {زُلۡفى}: وتُدني إليه، وإنَّما الذي يقرِّبُ منه زلفى الإيمان بما جاء به المرسلونَ والعملُ الصالح الذي هو من لوازم الإيمان؛ فإنَّ أولئك لهم الجزاء عند الله تعالى مضاعفاً الحسنة بعشر أمثالها إلى سبعمائةِ ضعفٍ إلى أضعافٍ كثيرة لا يعلمُها إلاَّ الله.","en":"Wealth and children are not what brings one near to Allah and draws one close to Him; what brings one near is faith in what the messengers brought and the righteous deed that is inseparable from faith. Those have the reward with Allah multiplied, each good deed ten times over up to seven hundred times and many more times that none knows but Allah."}},{"id":"fitna","ch":"haqiqa","t":"الأموال والأولاد فتنة","r":[8,28,28],"n":"تصف الآية الأموال والأولاد بأنها فتنة، وتختم بأن عند الله أجراً عظيماً.","wd":0,"q":{"w":"السعدي","bk":"saadi","s":8,"ay":28,"x":"ولما كان العبد ممْتَحَناً بأمواله وأولاده، فربما حمله محبَّتهُ ذلك على تقديم هوى نفسه على أداء أمانته؛ أخبر الله تعالى أنَّ الأموال والأولاد فتنةٌ يبتلي الله بهما عباده، وأنها عاريَّة ستؤدَّى لمن أعطاها وتردُّ لمن استَوْدَعَها.","en":"Since a servant is tested through his wealth and children, and his love for them may lead him to put his own desire before fulfilling his trust, Allah informed us that wealth and children are a trial with which He tests His servants, and that they are a loan that will be returned to the one who gave it and given back to the one who entrusted it."}},{"id":"lahw","ch":"haqiqa","t":"لا تلهكم أموالكم ولا أولادكم عن ذكر الله","r":[63,9,9],"n":"تنهى الآية المؤمنين أن تشغلهم أموالهم وأولادهم عن ذكر الله، وتجعل من فعل ذلك من الخاسرين.","wd":0,"q":{"w":"السعدي","bk":"saadi","s":63,"ay":9,"x":"يأمر تعالى عباده المؤمنين بالإكثار من ذِكْرِه؛ فإنَّ في ذلك الربح والفلاح والخيراتِ الكثيرةَ، وينهاهم أنْ تَشْغَلَهم أموالُهم وأولادُهم عن ذِكره؛ فإنَّ محبَّة المال والأولاد مجبولةٌ عليها أكثر النفوس، فتقدِّمها على محبة الله، وفي ذلك الخسارة العظيمة، ولهذا قال تعالى:{ومَن يفعلۡ ذلك}؛ أي: يُلْهِهِ مالُه وولدُه عن ذكر الله، {فأولئك هم الخاسرونَ}: للسعادة الأبديَّة والنعيم المقيم؛ لأنَّهم آثروا ما يفنى على ما يبقى؛ قال تعالى:{إنَّما أموالكم وأولادُكم فتنةٌ والله عنده أجرٌ عظيمٌ}.","en":"He commands His believing servants to remember Him often, for in that is profit, success and abundant good, and forbids them to let their wealth and children distract them from remembering Him; for love of wealth and children is naturally in most souls, so they put them before love of Allah, and in that is great loss. Hence He said: \"And whoever does that\", meaning whoever is distracted by his wealth and child from the remembrance of Allah, \"it is those who are the losers\", of everlasting happiness and lasting bliss, because they preferred what perishes over what remains. He said: \"Your wealth and your children are only a trial, and with Allah is a great reward\"."}},{"id":"qalb","ch":"haqiqa","t":"يوم لا ينفع مال ولا بنون إلا من أتى الله بقلب سليم","r":[26,88,89],"n":"تبيّن الآيتان أن المال والبنين لا ينفعان يوم القيامة، وأن النافع من أتى الله بقلب سليم.","wd":0,"q":{"w":"السعدي","bk":"saadi","s":26,"ay":88,"x":"{ولا تُخۡزِني يَوۡمَ يُبۡعَثونَ}؛ أي: بالتوبيخ على بعض الذُّنوب والعقوبةِ عليها والفضيحة، بل أسْعِدْني في ذلك اليوم الذي لا يَنْفَعُ فيه مالٌ ولا بنونٌ؛ {إلاَّ مَنۡ أتى الله بقلبٍ سليم}: فهذا الذي ينفعُهُ عندَك، وهذا الذي ينجو من العقاب ويستحقُّ جزيل الثواب.","en":"\"And do not disgrace me on the Day they are resurrected\", that is, by rebuke for some sins, punishment for them and public shame; rather make me happy on that day on which neither wealth nor children will benefit \"except one who comes to Allah with a sound heart\": this is what benefits him with You, this is the one who is saved from punishment and deserves abundant reward."}},{"id":"mashi","ch":"kasb","t":"فامشوا في مناكبها وكلوا من رزقه","r":[67,15,15],"n":"تذكر الآية أن الله جعل الأرض ذلولاً، وتأمر بالمشي في مناكبها والأكل من رزقه، وتختم بأن إليه النشور.","wd":0,"q":{"w":"السعدي","bk":"saadi","s":67,"ay":15,"x":"أي: هو الذي سخَّر لكم الأرضَ وذَلَّلها؛ لتدرِكوا منها كلَّ ما تعلقت به حاجتُكم من غرسٍ وبناءٍ وحرثٍ وطرقٍ يُتَوَصَّلُ بها إلى الأقطار النائية والبلدان الشاسعة، {فامشوا في مناكِبِها}؛ أي: لطلب الرزق والمكاسب، {وكُلوا من رزقِهِ وإليه النشورُ}؛ أي: بعد أن تنتقلوا من هذه الدار التي جَعَلَها الله امتحاناً وبلغةً يُتَبَلَّغُ بها إلى الدار الآخرة؛ تُبعثون بعد موتكم وتُحشرون إلى الله؛ ليجازِيَكم بأعمالكم الحسنة والسيئة.","en":"That is, He it is who subjected the earth to you and made it tractable, so that you may attain from it all that your need is attached to, of planting, building, tilling and roads by which one reaches distant regions and far-off lands; \"so walk in its tracts\", that is, to seek provision and earnings, \"and eat of His provision, and to Him is the resurrection\": after you pass from this abode that Allah made a test and a means of provision for reaching the Hereafter, you will be raised after your death and gathered to Allah, who will recompense you for your good and bad deeds."}},{"id":"ibtigha","ch":"kasb","t":"فانتشروا في الأرض وابتغوا من فضل الله","r":[62,10,10],"n":"تأمر الآية بعد قضاء الصلاة بالانتشار في الأرض وابتغاء فضل الله مع الإكثار من ذكره.","wd":0,"q":{"w":"السعدي","bk":"saadi","s":62,"ay":10,"x":"وهذا الأمر بترك البيع موقَّت مدَّة الصلاة؛ {فإذا قُضِيَتِ الصلاةُ فانتشروا في الأرض}: لطلب المكاسب والتجارات، ولما كان الاشتغال بالتجارة مَظِنَّةُ الغفلة عن ذكر الله؛ أمر الله بالإكثار من ذكره؛ لينجبر بهذا، فقال:{واذكروا الله كثيراً}؛ أي: في حال قيامكم وقعودكم وعلى جنوبكم، {لعلَّكم تفلحون}: فإنَّ الإكثار من ذِكْر الله أكبر أسباب الفلاح.","en":"This command to leave off selling is limited to the duration of the prayer; \"then when the prayer has been concluded, disperse in the land\", to seek earnings and trade. Since busying oneself with trade is a likely cause of heedlessness of the remembrance of Allah, Allah commanded remembering Him often, to make up for it, so He said: \"and remember Allah often\", that is, standing, sitting and lying on your sides, \"that you may succeed\": for increasing the remembrance of Allah is the greatest of the causes of success."}},{"id":"darb","ch":"kasb","t":"وآخرون يضربون في الأرض يبتغون من فضل الله","r":[73,20,20],"n":"تذكر الآية من الناس من يسافر في الأرض يبتغي من فضل الله، وتقرن ذلك بالصلاة والزكاة والقرض الحسن.","wd":0,"q":{"w":"السعدي","bk":"saadi","s":73,"ay":20,"x":"{وآخرون يضرِبون في الأرض يبتغونَ من فضل الله}؛ أي: وعلم أنَّ منكم مسافرين يسافرون للتجارة؛ ليستغنوا عن الخلق، ويتكفَّفوا عنهم ؛ أي: فالمسافر حالُهُ تناسِبُ التخفيف، ولهذا خفَّف عنه في صلاة الفرض، فأبيح له جمعُ الصلاتين في وقتٍ واحدٍ وقصرُ الصَّلاة الرُّباعية.","en":"\"And others travel throughout the land seeking of Allah's bounty\", that is: He knew that among you are travellers who travel for trade, so that they may be free of need of people and refrain from begging from them. The state of the traveller calls for lightening, which is why the obligatory prayer was lightened for him: he is permitted to combine two prayers in one time and to shorten the four-unit prayer."}},{"id":"tayyib","ch":"kasb","t":"كلوا مما في الأرض حلالاً طيباً","r":[2,168,168],"n":"تخاطب الآية الناس بالأكل مما في الأرض حلالاً طيباً، وتنهى عن اتباع خطوات الشيطان.","wd":0,"q":{"w":"السعدي","bk":"saadi","s":2,"ay":168,"x":"هذا خطاب للناس كلهم مؤمنهم وكافرهم، فامتن عليهم بأن أمرهم أن يأكلوا من جميع ما في الأرض من حبوب وثمار وفواكه وحيوانات حالة كونها {حلالاً}؛ أي: محللاً لكم تناوله ليس بغصب ولا سرقة ولا محصلاً بمعاملة محرمة أو على وجه محرم أو معيناً على محرم {طيباً}؛ أي: ليس بخبيث كالميتة والدم ولحم الخنزير والخبائث كلها.","en":"This is an address to all people, believers and disbelievers alike. He reminded them of His favour by commanding them to eat of all that is on earth of grains, fruits and animals, as \"lawful\", meaning made lawful for you to take, not by seizure or theft, nor gained through a forbidden transaction or in a forbidden way, nor helping toward something forbidden, and \"good\", meaning not vile like carrion, blood, pork and all vile things."}},{"id":"khasara","ch":"tijara","t":"فما ربحت تجارتهم","r":[2,16,16],"n":"تصف الآية من اشتروا الضلالة بالهدى بأنهم لم تربح تجارتهم وما كانوا مهتدين.","wd":0,"q":{"w":"السعدي","bk":"saadi","s":2,"ay":16,"x":"أولئك؛ أي: المنافقون الموصوفون بتلك الصفات {الذين اشتروا الضلالة بالهدى}؛ أي: رغبوا في الضلالة رغبة المشتري في السلعة ، التي ـ من رغبته فيها ـ يبذل فيها الأموال النفيسة، وهذا من أحسن الأمثلة، فإنه جعل الضلالة التي هي غاية الشر كالسلعة، وجعل الهدى الذي هو غاية الصلاح بمنزلة الثمن، فبذلوا الهدى رغبة عنه في الضلالة رغبة فيها، فهذه تجارتهم؛ فبئس التجارة، وهذه صفقتهم؛ فبئست الصفقة.","en":"Those are the hypocrites described with those qualities, \"who bought misguidance for guidance\", that is, they desired misguidance as a buyer desires a commodity for which, from his desire for it, he pays precious wealth. This is one of the finest examples: He made misguidance, the utmost evil, like the commodity, and guidance, the utmost goodness, like the price; they paid out guidance, turning away from it, for misguidance, desiring it. This is their trade, and what an evil trade; this is their bargain, and what an evil bargain."}},{"id":"tunji","ch":"tijara","t":"هل أدلكم على تجارة تنجيكم من عذاب أليم","r":[61,10,12],"n":"تعرض الآيات تجارة تنجي من عذاب أليم: الإيمان بالله ورسوله والجهاد بالأموال والأنفس.","wd":0,"q":{"w":"السعدي","bk":"saadi","s":61,"ay":10,"x":"هذه وصيةٌ ودلالةٌ وإرشادٌ من أرحم الراحمين لعباده المؤمنين لأعظم تجارةٍ وأجلِّ مطلوب وأعلى مرغوبٍ يحصل بها النجاة من العذاب الأليم والفوز بالنعيم المقيم، وأتى بأداة العرض الدالَّة على أنَّ هذا أمرٌ يرغب فيه كلُّ متصبِّر ويسمو إليه كل لبيبٍ.","en":"This is a counsel, a guidance and direction from the Most Merciful of the merciful to His believing servants toward the greatest trade, the most precious thing sought and the highest thing desired, by which one gains salvation from painful punishment and success in lasting bliss. He used the particle of offering, which indicates that this is something every patient person longs for and every wise person aspires to."}},{"id":"ishtara","ch":"tijara","t":"إن الله اشترى من المؤمنين أنفسهم وأموالهم بأن لهم الجنة","r":[9,111,111],"n":"تصوّر الآية العلاقة بين الله والمؤمنين صفقة بيع: الثمن الجنة والمبيع الأنفس والأموال.","wd":0,"q":{"w":"السعدي","bk":"saadi","s":9,"ay":111,"x":"وإذا أردت أن تعرف مقدار الصفقة؛ فانظُرْ إلى المشتري؛ مَنْ هو؟ وهو الله جلَّ جلاله، وإلى العِوَضِ، وهو أكبر الأعواض وأجلُّها؛ جنات النعيم، وإلى الثمن المبذول فيها، وهو النفس والمال، الذي هو أحبُّ الأشياء للإنسان، وإلى مَن جرى على يديه عقدُ هذا التبايُع، وهو أشرف الرسل، وبأيِّ كتاب رُقِمَ؟","en":"If you want to know the size of the bargain, look at the buyer, who is he? He is Allah, Majestic is His majesty; and at the compensation, which is the greatest and most precious of compensations, the gardens of bliss; and at the price paid for it, which is self and wealth, the dearest of things to a person; and at the one through whose hands this sale was concluded, the noblest of messengers; and in which book was it written?"}},{"id":"tatfif","ch":"mizan","t":"ويل للمطففين","r":[83,1,6],"n":"تتوعد الآيات المطففين الذين يستوفون إذا اكتالوا ويُنقصون إذا كالوا أو وزنوا، وتنكر عليهم غفلتهم عن البعث.","wd":0,"q":{"w":"السعدي","bk":"saadi","s":83,"ay":1,"x":"{ويلٌ}: كلمة عذابٍ وعقابٍ ، {للمطفِّفين}: وفسر الله المطفِّفين بأنهم {الذين إذا اكتالوا على الناس}؛ أي: أخذوا منهم وفاءً لهم عمَّا قِبَلَهم ، يستوفونه كاملاً من غير نقصٍ، {وإذا كالوهم أو وَزَنوهم}؛ أي: إذا أعطوا الناس حقَّهم الذي لهم عليهم بكيل أو وزن، {يُخۡسِرونَ}؛ أي: ينقصِونَهم ذلك إمَّا بمكيال وميزان ناقصين، أو بعدم ملء المِكْيال والميزان، أو بغير ذلك؛ فهذا سرقةٌ لأموال الناس وعدمُ إنصاف لهم منهم.","en":"\"Woe\", a word of torment and punishment, \"to those who give less than due\", and Allah explained those who give less as \"those who, when they take a measure from people, take it in full\", meaning they take from them what is due to them from others, completely without deficiency, \"but when they give by measure or weight\", that is, when they give people their right due from them by measure or weight, \"they cause loss\", meaning they reduce it, either with a deficient measure and scale, or by not filling the measure and scale, or by other means; this is theft of people's wealth and injustice toward them."}},{"id":"shuayb","ch":"mizan","t":"أوفوا المكيال والميزان بالقسط ولا تبخسوا الناس أشياءهم","r":[11,85,87],"n":"تنقل الآيات قول شعيب لقومه بالإيفاء بالقسط وترك البخس وعدم الإفساد، وجوابهم أنهم يفعلون في أموالهم ما يشاؤون.","wd":0,"q":{"w":"السعدي","bk":"saadi","s":11,"ay":85,"x":"{ويا قوم أوفوا المكيالَ والميزان بالقِسۡطِ}؛ أي: بالعدل الذي ترضَوْن أن تعطوه، {ولا تَبخَسوا الناس أشياءهم}؛ أي: لا تنقصوا من أشياء الناس، فتسرقوها بأخذها بنقص المكيال والميزان، {ولا تَعۡثَوۡا في الأرض مفسِدينَ}: فإنَّ الاستمرار على المعاصي يفسِدُ الأديان والعقائد والدِّين والدُّنيا ويهلِكُ الحرثَ والنسل.","en":"\"And O my people, give full measure and weight in justice\", that is, with the justice you would be pleased to be given, \"and do not deprive people of their due\", meaning do not reduce people's things, stealing them by taking with a deficient measure and scale, \"and do not commit abuse on the earth, spreading corruption\": for persisting in sins corrupts religion, beliefs, this world and the next, and destroys crops and offspring."}},{"id":"mizan55","ch":"mizan","t":"والسماء رفعها ووضع الميزان","r":[55,7,9],"n":"تذكر الآيات أن الله وضع الميزان، وتنهى عن الطغيان فيه وتأمر بإقامة الوزن بالقسط وعدم الإخسار.","wd":0,"q":{"w":"السعدي","bk":"saadi","s":55,"ay":7,"x":"{والسماء رفعها}: سقفاً للمخلوقات الأرضيَّة، {ووضع}[اللَّه]{الميزان}؛ أي: العدل بين العبادِ في الأقوال والأفعال، وليس المراد به الميزان المعروف وحده، بل هو كما ذكرنا؛ يدخل فيه الميزان المعروف والمكيال الذي تُكال به الأشياء والمقادير والمساحات التي تُضْبَط بها المجهولات والحقائق التي يُفْصَل بها بين المخلوقات ويُقام بها العدل بينهم، ولهذا قال:{ألاَّ تَطۡغَوۡا في الميزان}؛ أي: أنزل الله الميزان لئلاَّ تتجاوزوا الحدَّ في الميزان؛ فإنَّ الأمر لو كان يرجع إلى عقولكم وآرائكم؛ لحصل من الخلل ما الله به عليم …","en":"\"And the heaven He raised\", as a roof for earthly creatures, \"and He set up the balance\", that is, justice between servants in words and deeds. By it is not meant the familiar scale alone, but as we mentioned it includes the familiar scale, the measure by which things are measured, the units by which unknowns are determined, and the truths by which creatures are distinguished and justice established among them. Hence He said: \"that you not transgress within the balance\", that is, Allah sent down the balance so that you do not exceed the limit in it; for if the matter returned to your minds and opinions, there would arise such disorder as Allah knows …"}},{"id":"laylnahar","ch":"infaq","t":"الذين ينفقون أموالهم بالليل والنهار سراً وعلانية","r":[2,274,274],"n":"تعد الآية المنفقين في الليل والنهار سراً وعلانية بأجرهم عند ربهم، وتنفي عنهم الخوف والحزن.","wd":0,"q":{"w":"السعدي","bk":"saadi","s":2,"ay":274,"x":"{الذين ينفقون أموالهم بالليل والنهار سراً وعلانية فلهم أجرهم عند ربهم ولا خوف عليهم ولا هم يحزنون}؛ فإن الله يظلهم بظله يوم لا ظل إلا ظله، وإن الله ينيلهم الخيرات ويدفع عنهم الأحزان والمخاوف والكريهات. وقوله:{فلهم أجرهم عند ربهم}؛ أي: كل أحد منهم بحسب حاله، وتخصيص ذلك بأنه عند ربهم يدل على شرف هذه الحال ووقوعها في الموقع الأكبر كما في الحديث الصحيح «إن العبد ليتصدق بالتمرة من كسب طيب فيتقبلها الجبار بيده فيربيها لأحدكم كما يربي أحدكم فَلُوَّه حتى تكون مثل الجبل العظيم».","en":"\"Those who spend their wealth by night and by day, secretly and publicly, will have their reward with their Lord, and no fear will there be concerning them, nor will they grieve\": Allah will shade them in His shade on the day when there is no shade but His, give them good things and remove from them griefs, fears and hated things. His words \"they will have their reward with their Lord\", that is, each one according to his state, and specifying that it is with their Lord indicates the nobility of this state and that it falls in the greatest place, as in the authentic hadith: \"A servant gives a date in charity from good earnings, and the Almighty accepts it in His hand and rears it for one of you as one of you rears his foal, until it becomes like a great mountain.\""}},{"id":"mann","ch":"infaq","t":"لا تبطلوا صدقاتكم بالمن والأذى","r":[2,264,264],"n":"تنهى الآية عن إبطال الصدقات بالمن والأذى، وتشبّه المنفق رياءً بصفوان عليه تراب.","wd":0,"q":{"w":"السعدي","bk":"saadi","s":2,"ay":264,"x":"فأما الأول فإنه لما كانت نفقته مقبولة مضاعفة لصدورها عن الإيمان والإخلاص التام {ابتغاء مرضاة الله وتثبيتاً من أنفسهم}؛ أي: ينفقون وهم ثابتون على وجه السماحة والصدق فمثل هذا العمل، {كمثل جنة بربوة}؛ وهو المكان المرتفع لأنه يتبين للرياح والشمس، والماء فيها غزير، فإن لم يصبها ذلك الوابل الغزير، حصل لها طلٌّ كافٍ لطيب منبتها وحسن أرضها وحصول جميع الأسباب الموفرة لنموها وازدهارها وإثمارها، ولهذا {آتت أكلها ضعفين}؛ أي: متضاعفاً، وهذه الجنة التي على هذا الوصف هي أعلى ما يطلبه الناس، فهذا العمل الفاضل بأعلى المنازل.","en":"As for the first, since his spending is accepted and multiplied, issuing from faith and complete sincerity, \"seeking the pleasure of Allah and certainty within themselves\", that is, they spend while firm, with generosity and truthfulness, the likeness of such a deed is \"like a garden on a height\", a raised place because it is exposed to the winds, the sun and the water, which is plentiful there; and if that heavy rain does not reach it, enough dew reaches it for the goodness of its soil and everything that supports its growth, flourishing and fruiting; hence \"it brought forth its fruit in double\", that is, multiplied. A garden of this description is the highest thing people seek, and this excellent deed is of the highest ranks."}},{"id":"birr","ch":"infaq","t":"لن تنالوا البر حتى تنفقوا مما تحبون","r":[3,92,92],"n":"تجعل الآية نيل البرّ مرتبطاً بالإنفاق مما يحب الإنسان، وتبيّن أن الله به عليم.","wd":0,"q":{"w":"السعدي","bk":"saadi","s":3,"ay":92,"x":"يعني {لن تنالوا} وتدركوا {البر}، الذي هو اسم جامع للخيرات وهو: الطريق الموصل إلى الجنة {حتى تنفقوا مما تحبون} من أطيب أموالكم وأزكاها، فإن النفقة من الطيب المحبوب للنفوس من أكبر الأدلة على سماحة النفس واتصافها بمكارم الأخلاق ورحمتها ورقتها، ومن أدل الدلائل على محبة الله وتقديم محبته على محبة الأموال التي جبلت النفوس على قوة التعلق بها، فمن آثر محبة الله على محبة نفسه فقد بلغ الذروة العليا من الكمال وكذلك من أنفق الطيبات وأحسن إلى عباد الله أحسن الله إليه ووفقه أعمالاً وأخلاقاً لا تحصل بدون هذه الحالة.","en":"He means: \"you will never attain\" and reach \"righteousness\", which is a comprehensive name for good things and is the road that leads to Paradise, \"until you spend from what you love\", from the best and purest of your wealth. For spending from the good that souls love is among the greatest proofs of generosity of soul, its noble character, mercy and gentleness, and among the clearest proofs of love for Allah and of putting His love before love of the wealth to which souls are naturally strongly attached. Whoever prefers love of Allah to love of himself has reached the highest summit of perfection; and likewise whoever spends good things and does good to Allah's servants, Allah does good to him and grants him deeds and character that are not attained without this state."}},{"id":"tazkiya","ch":"infaq","t":"خذ من أموالهم صدقة تطهرهم وتزكيهم بها","r":[9,103,103],"n":"تأمر الآية نبيه بأخذ الصدقة من أموالهم تطهرهم وتزكيهم بها وبالدعاء لهم.","wd":0,"q":{"w":"السعدي","bk":"saadi","s":9,"ay":103,"x":"قال تعالى لرسوله ومَنْ قام مقامه آمراً له بما يطهِّر المؤمنين ويتمِّم إيمانهم: {خُذۡ من أموالهم صدقةً}: وهي الزكاة المفروضة، {تطهِّرُهم وتزكِّيهم بها}؛ أي: تطهِّرهم من الذُّنوب والأخلاق الرذيلة، {وتزكِّيهم}؛ أي: تنميهم، وتزيد في أخلاقهم الحسنة وأعمالهم الصالحة، وتزيد في ثوابهم الدنيوي والأخروي، وتنمي أموالهم، {وصَلِّ عليهم}؛ أي: ادع لهم؛ أي: للمؤمنين عموماً وخصوصاً عندما يدفعون إليك زكاة أموالهم.","en":"Allah said to His Messenger, and whoever takes his place, commanding him with what purifies the believers and completes their faith: \"Take from their wealth a charity\", which is the obligatory zakat, \"by which you purify them and cause them to grow\", that is, purify them of sins and base character; \"and cause them to grow\" means to increase their good character and righteous deeds, increase their reward in this world and the next, and make their wealth grow; \"and invoke blessings upon them\", that is, pray for them, for the believers in general and specifically when they hand you the zakat of their wealth."}},{"id":"haqq","ch":"infaq","t":"وفي أموالهم حق للسائل والمحروم","r":[51,19,19],"n":"تذكر الآية من صفات المحسنين أن في أموالهم حقاً للسائل والمحروم.","wd":0,"q":{"w":"السعدي","bk":"saadi","s":51,"ay":19,"x":"{وفي أموالهم حقٌّ}: واجبٌ ومستحبٌّ {للسائل والمحروم}؛ أي: للمحتاجين الذين يطلبون من الناس والذين لا يسألونهم.","en":"\"And in their wealth is a right\", obligatory and recommended, \"for the beggar and the deprived\", that is, for the needy who ask people and those who do not ask them."}},{"id":"qard","ch":"infaq","t":"من ذا الذي يقرض الله قرضاً حسناً فيضاعفه له","r":[2,245,245],"n":"تدعو الآية إلى إقراض الله قرضاً حسناً، وتعد بتضعيفه أضعافاً كثيرة، وتذكر أن الله يقبض ويبسط.","wd":0,"q":{"w":"السعدي","bk":"saadi","s":2,"ay":245,"x":"وتأمل هذا الحث اللطيف على النفقة وإن المنفق قد أقرض الله الملي الكريم ووعده المضاعفة الكثيرة كما قال تعالى:{مثل الذين ينفقون أموالهم في سبيل الله كمثل حبة أنبتت سبع سنابل في كل سنبلة مائة حبة، والله يضاعف لمن يشاء والله واسع عليم}؛ ولما كان المانع الأكبر من الإنفاق خوفَ الإملاقِ أخبر تعالى أنَّ الغنى والفقرَ بيد الله، وأنه يقبض الرزق على من يشاء ويبسطه على من يشاء، فلا يتأخر من يريد الإنفاق خوفَ الفقر، ولا يظن أنه ضائع، بل مرجع العباد كلهم إلى الله فيجد المنفقون والعاملون أجرهم عنده مدخراً أحوج ما يكونون إليه …","en":"Consider this gentle urging to spend, and that the one who spends has lent to Allah, the Rich and Generous, who promised him abundant multiplication, as He said: \"The example of those who spend their wealth in the way of Allah is like a seed that grows seven spikes; in each spike is a hundred grains; and Allah multiplies for whom He wills, and Allah is Vast and Knowing\". Since the greatest obstacle to spending is fear of poverty, He informed us that wealth and poverty are in Allah's hand and that He withholds provision from whom He wills and extends it to whom He wills; so let one who wants to spend not hold back for fear of poverty, nor think that it is lost, for all servants return to Allah and those who spend and act will find their reward stored with Him when they need it most …"}},{"id":"itam","ch":"infaq","t":"ويطعمون الطعام على حبه مسكيناً ويتيماً وأسيراً","r":[76,8,10],"n":"تمدح الآيات من يطعمون الطعام على حبه مسكيناً ويتيماً وأسيراً لوجه الله لا يريدون جزاءً ولا شكوراً.","wd":0,"q":{"w":"السعدي","bk":"saadi","s":76,"ay":8,"x":"{ويطعِمونَ الطَّعامَ على حبِّه}؛ أي: وهم في حال يحبُّون فيها المال والطعام، لكنَّهم قدَّموا محبَّة الله على محبَّة نفوسهم، ويتحرَّوْن في إطعامهم أولى الناس وأحوجَهم، {مسكيناً ويتيماً وأسيراً}: ويقصدون بإنفاقهم وإطعامهم وجهَ الله تعالى، ويقولون بلسان الحال:{إنَّما نطعِمُكم لوجه الله لا نريدُ منكم جزاءً ولا شكوراً}؛ أي: لا جزاءً ماليًّا ولا ثناءً قوليًّا، {إنا نخاف من ربِّنا يوماً عبوساً}؛ أي: شديد الجهمة والشرِّ، {قمطريراً}؛ أي: ضنكاً ضيقاً.","en":"\"And they give food, in spite of love for it\", that is, though they love wealth and food, yet they put love of Allah before love of themselves, and they seek out the most deserving and neediest, \"the poor, the orphan and the captive\", intending by their spending and feeding the face of Allah, saying in the tongue of their state: \"We feed you only for the countenance of Allah; we wish not from you reward or gratitude\", that is, no reward in wealth and no praise in words; \"Indeed, we fear from our Lord a Day austere\", that is, very grim and evil, \"distressful\", that is, hard and narrow."}},{"id":"fay","ch":"infaq","t":"كي لا يكون دولة بين الأغنياء منكم","r":[59,7,7],"n":"تعلّل الآية توزيع الفيء على أصناف معينة بقوله تعالى: كي لا يكون دولة بين الأغنياء منكم.","wd":0,"q":{"w":"السعدي","bk":"saadi","s":59,"ay":7,"x":"وإنَّما قدَّر الله هذا التقدير وحصر الفيء في هؤلاء المعيَّنين؛ لكي {لا يكونَ دُولَةً}؛ أي: مداولةً واختصاصاً {بين الأغنياءِ منكم}: فإنَّه لو لم يقدِّره؛ لتداولته الأغنياءُ الأقوياء، ولما حَصَلَ لغيرهم من العاجزين منه شيءٌ، وفي ذلك من الفساد ما لا يعلمه إلا الله؛ كما أنَّ في اتِّباع أمر الله وشرعه من المصالح ما لا يدخل تحت الحصر، ولذلك أمر الله بالقاعدة الكلِّيَّة والأصل العام، فقال:{وما آتاكُمُ الرسولُ فخذوهُ وما نَهاكم عنهُ فانتَهوا}: وهذا شاملٌ لأصول الدين وفروعه ظاهره وباطنه …","en":"Allah ordained this measure and limited the spoils to these specified groups so that \"it will not be a perpetual distribution\", that is, circulating and monopolised, \"among the rich among you\". Had He not ordained it, the rich and strong would have exchanged it among themselves and the weak would have gained nothing from it, and in that is corruption known only to Allah; just as in following Allah's command and law are benefits beyond count. So He commanded the general rule and universal principle, saying: \"And what the Messenger gives you, take; and what he forbids you, refrain from\": this covers the roots of religion and its branches, outward and inward …"}},{"id":"faqir","ch":"infaq","t":"للفقراء الذين أحصروا في سبيل الله لا يستطيعون ضرباً في الأرض","r":[2,273,273],"n":"تذكر الآية فقراء حُبسوا عن الكسب وهم متعففون يحسبهم الجاهل أغنياء من التعفف لا يسألون الناس إلحافاً.","wd":0,"q":{"w":"السعدي","bk":"saadi","s":2,"ay":273,"x":"يعني أنه ينبغي أن تتحروا بصدقاتكم الفقراء الذين حبسوا أنفسهم في سبيل الله وعلى طاعته، وليس لهم إرادة في الاكتساب أو ليس لهم قدرة عليه وهم يتعففون إذا رآهم الجاهل ظن أنهم أغنياء {لا يسألون النّاس إلحافاً}؛ فهم لا يسألون بالكلية وإن سألوا اضطراراً لم يلحفوا في السؤال، فهذا الصنف من الفقراء أفضل ما وضعت فيهم النفقات لدفع حاجتهم وإعانة لهم على مقصدهم وطريق الخير وشكراً لهم على ما اتصفوا به من الصبر والنظر إلى الخالق لا إلى الخلق …","en":"He means that you should seek out for your charity the poor who have confined themselves to the cause of Allah and to obedience to Him, who have no intention of earning or no ability for it, and who are so restrained that when an ignorant person sees them he thinks them wealthy; \"they do not ask people persistently\", so they do not ask at all, and if they ask out of necessity they do not press in asking. This kind of poor is the best place to put spending, to relieve their need, help them toward their aim and the path of good, and to thank them for the patience with which they are described and for looking to the Creator, not to creation …"}},{"id":"tabdhir","ch":"itidal","t":"ولا تبذر تبذيراً","r":[17,26,27],"n":"تأمر الآيات بإيتاء ذي القربى والمسكين وابن السبيل حقهم، وتنهى عن التبذير وتجعل المبذرين إخوان الشياطين.","wd":0,"q":{"w":"السعدي","bk":"saadi","s":17,"ay":26,"x":"يقول تعالى: {وآت ذا القُربى حقَّه}: من البرِّ والإكرام الواجب والمسنون، وذلك الحقُّ يتفاوت بتفاوت الأحوال والأقارب والحاجة وعدمها والأزمنة، {والمسكينَ}: آته حقَّه من الزَّكاة ومن غيرها؛ لتزول مسكنتُه، {وابنَ السبيل}: وهو الغريب المنقطع به عن بلده، فيُعْطى الجميع من المال، على وجهٍ لا يضرُّ المعطي، ولا يكون زائداً على المقدار اللائق؛ فإنَّ ذلك تبذيرٌ، قد نهى الله عنه وأخبر: إنَّ المبذِّرين {إخوانُ الشياطين}: لأنَّ الشيطان لا يدعو إلاَّ إلى كلِّ خَصلة ذميمةٍ، فيدعو الإنسان إلى البخل والإمساك؛ فإذا عصاه …","en":"The Exalted says: \"And give the relative his right\", of obligatory and recommended kindness and honour, a right that varies with circumstances, relatives, need or its absence, and times; \"and the poor\": give him his right from zakat and other than it, so that his poverty is lifted; \"and the traveller\", the stranger cut off from his land. All are given from wealth, in a way that does not harm the giver and does not exceed the fitting amount, for that is wastefulness, which Allah has forbidden, and He informed us that the wasteful are \"brothers of the devils\", because Satan calls only to every blameworthy trait, so he calls a person to miserliness and withholding; then if he disobeys him …"}},{"id":"wasat","ch":"itidal","t":"ولا تجعل يدك مغلولة إلى عنقك ولا تبسطها كل البسط","r":[17,29,29],"n":"ترسم الآية الوسط: لا إمساك كأن اليد مغلولة إلى العنق، ولا بسط كامل يجعل صاحبه ملوماً محسوراً.","wd":0,"q":{"w":"السعدي","bk":"saadi","s":17,"ay":29,"x":"وقال هنا: {ولا تجعل يَدَكَ مغلولةً إلى عنقك}: كناية عن شدة الإمساك والبخل، {ولا تَبۡسُطۡها كلَّ البسط}: فتنفق فيما لا ينبغي أو زيادة على ما ينبغي، {فتقعدَ}: إن فعلت ذلك {مَلوماً}؛ أي: تُلام على ما فعلتَ، {مَحۡسوراً}؛ أي: حاسر اليد فارغها؛ فلا بقي ما في يدك من المال، ولا خَلَفَه مدحٌ وثناءٌ.","en":"He said here: \"And do not make your hand shackled to your neck\", a metaphor for extreme withholding and miserliness, \"and do not extend it completely\", spending where one should not or more than one should, \"so you would become\" if you did that \"blamed\", that is, you would be blamed for what you did, \"insolvent\", that is, empty-handed: neither the wealth in your hand remains, nor does praise and commendation take its place."}},{"id":"ibad","ch":"itidal","t":"والذين إذا أنفقوا لم يسرفوا ولم يقتروا","r":[25,67,67],"n":"تصف الآية عباد الرحمن بأنهم إذا أنفقوا لم يسرفوا ولم يقتروا وكان بين ذلك قواماً.","wd":0,"q":{"w":"السعدي","bk":"saadi","s":25,"ay":67,"x":"{والذين إذا أنفَقوا}: النفقاتِ الواجبةَ والمستحبةَ {لم يُسۡرِفوا}: بأن يَزيدوا على الحدِّ فيدخُلوا في قسم التبذير، {ولم يَقۡتُروا}: فيدخلوا في باب البُخْل والشُّحِّ، وإهمال الحقوق الواجبة، {وكان}: إنفاقُهم {بينَ ذلك}: بين الإسراف والتقتير {قَواماً}: يبذُلون في الواجبات من الزَّكَواتِ والكفاراتِ والنفقاتِ الواجبةِ وفيما ينبغي على الوجه الذي يَنْبَغي من غير ضررٍ ولا ضِرارٍ، وهذا من عدلهم واقتصادهم.","en":"\"And those who, when they spend\", the obligatory and recommended expenditures, \"are neither extravagant\", exceeding the limit and entering the category of squandering, \"nor niggardly\", entering the category of miserliness and neglecting obligatory rights, \"and it is between that\", between extravagance and stinginess, \"moderate\": they spend on obligations such as zakat, expiations and obligatory maintenance, and on what is fitting, in the proper way without harm or reciprocal harm; and this is part of their justice and moderation."}},{"id":"israf","ch":"itidal","t":"كلوا واشربوا ولا تسرفوا","r":[7,31,31],"n":"تأمر الآية بالأكل والشرب وتنهى عن الإسراف وتذكر أن الله لا يحب المسرفين.","wd":0,"q":{"w":"السعدي","bk":"saadi","s":7,"ay":31,"x":"ثم قال:{وكلوا واشربوا}؛ أي: مما رزقكم الله من الطيبات، {ولا تسرِفوا}: في ذلك، والإسراف إما أن يكون بالزيادة على القدر الكافي والشره في المأكولات التي تضر بالجسم، وإما أن يكون بزيادة الترفُّه والتنوُّق في المآكل والمشارب واللباس، وإما بتجاوز الحلال إلى الحرام. {إنَّه لا يحبُّ المسرفين}: فإن السرف يبغضه الله، ويضرُّ بدن الإنسان ومعيشته، حتى إنه ربما أدَّت به الحالُ إلى أن يعجز عما يجب عليه من النفقات.","en":"Then He said: \"And eat and drink\", that is, of the good things Allah has provided you, \"but be not excessive\" in that. Excess is either exceeding the sufficient amount and greed for foods that harm the body, or increasing luxury and refinement in food, drink and clothing, or going beyond the lawful to the forbidden. \"Indeed, He does not like the excessive\": for Allah hates excess, and it harms a person's body and livelihood, so that it may even bring him to being unable to pay what is obligatory upon him of expenses."}},{"id":"bukhl","ch":"itidal","t":"ولا يحسبن الذين يبخلون بما آتاهم الله من فضله","r":[3,180,180],"n":"تنفي الآية أن يكون البخل بما آتى الله من فضله خيراً لأهله، وتجعله شراً لهم، وتتوعدهم بالتطويق يوم القيامة.","wd":0,"q":{"w":"السعدي","bk":"saadi","s":3,"ay":180,"x":"أي: ولا يظن الذين يبخلون؛ أي: يمنعون ما عندهم مما آتاهم الله من فضله من المال والجاه والعلم وغير ذلك، مما منحهم الله وأحسن إليهم به، وأمرهم ببذل ما لا يضرهم منه لعباده فبخلوا بذلك، وأمسكوه وضنوا به على عباد الله، وظنوا أنه خير لهم بل هو شر لهم في دينهم ودنياهم وعاجلهم وآجلهم، {سيطوقون ما بخلوا به يوم القيامة}؛ أي يجعل ما بخلوا به طوقاً في أعناقهم يعذبون به كما ورد في الحديث الصحيح:«إن البخيل يمثل له ماله يوم القيامة شجاعاً أقرع له زبيبتان يأخذ بلهزمته يقول: أنا مالك، أنا كنزك» …","en":"That is, let not those who are miserly, that is, who withhold what they have of what Allah gave them of His bounty, wealth, rank, knowledge and other things with which Allah favoured them and did good to them, and who commanded them to spend of it for His servants what does not harm them, but they were miserly with it, held it back and begrudged it to Allah's servants, thinking that it is good for them, whereas it is evil for them in their religion and worldly life, in the near and the far; \"they will be encircled by what they withheld on the Day of Resurrection\", that is, what they were miserly with will be made a collar on their necks with which they are punished, as it came in the authentic hadith: \"The miser's wealth will be made to appear to him on the Day of Resurrection as a bald serpent with two black spots, taking him by his jaws, saying: I am your wealth, I am your treasure\" …"}},{"id":"nasib","ch":"itidal","t":"وابتغ فيما آتاك الله الدار الآخرة ولا تنس نصيبك من الدنيا","r":[28,77,77],"n":"تنقل الآية نصيحة قوم قارون له: أن يبتغي بما آتاه الله الدار الآخرة ولا ينسى نصيبه من الدنيا ويحسن كما أحسن الله إليه.","wd":0,"q":{"w":"السعدي","bk":"saadi","s":28,"ay":77,"x":"{وابۡتَغ فيما آتاكَ الله الدارَ الآخرةَ}؛ أي: قد حصل عندك من وسائل الآخرة ما ليس عند غيرِك من الأموال، فابتغِ بها ما عندَ الله، وتصدَّقْ، ولا تقتصرْ على مجرَّدِ نيل الشهوات وتحصيل اللذَّات، {ولا تنسَ نصيبَكَ من الدُّنيا}؛ أي: لا نأمُرُك أن تتصدَّق بجميع مالِكَ وتبقى ضائعاً، بلْ أنفِقْ لآخِرَتِكَ واستمتِعْ بدُنياك استمتاعاً لا يَثْلُمُ دينَك ولا يضرُّ بآخرتك، {وأحسِنۡ}: إلى عباد الله {كما أحسنَ اللهُ}: عليك بهذه الأموال، {ولا تَبۡغِ الفسادَ في الأرض}: بالتكبُّر والعمل بمعاصي الله والاشتغال بالنِّعَم عن المنعم.","en":"\"But seek, through that which Allah has given you, the home of the Hereafter\", that is: you have gained of the means of the Hereafter, in wealth, what others do not have; so seek with it what is with Allah, give in charity, and do not limit yourself to merely attaining desires and gaining pleasures; \"and do not forget your share of the world\", meaning we do not command you to give all your wealth in charity and remain lost, but spend for your Hereafter and enjoy your worldly life in a way that does not breach your religion or harm your Hereafter; \"and do good\", to Allah's servants, \"as Allah has done good to you\" with this wealth, \"and do not seek corruption in the land\", through arrogance, disobedience to Allah and busying oneself with blessings to the neglect of the Giver."}},{"id":"layl","ch":"itidal","t":"وأما من بخل واستغنى","r":[92,8,11],"n":"تقابل الآيات بين من أعطى واتقى فييسّر لليسرى، ومن بخل واستغنى فييسّر للعسرى، وتنفي عنه نفع ماله إذا تردى.","wd":0,"q":{"w":"السعدي","bk":"saadi","s":92,"ay":8,"x":"{وأمَّا مَن بَخِلَ}: بما أمِرَ به، فترك الإنفاق الواجب والمستحبَّ، ولم تسمح نفسه بأداء ما وجب لله، {واستغنى}: عن الله، فترك عبوديَّته جانباً، ولم ير نفسه مفتقرةً غاية الافتقار إلى ربِّها، الذي لا نجاة لها ولا فوز ولا فلاح إلاَّ بأن يكون هو محبوبها ومعبودها الذي تقصده وتتوجَّه إليه، {وكذَّب بالحُسنى}؛ أي: بما أوجب الله على العباد التصديق به من العقائد الحسنة، {فسنيسِّرهُ للعُسۡرى}؛ أي: للحالة العسرة والخصال الذَّميمة؛ بأن يكون ميسَّراً للشرِّ أينما كان ومقيَّضاً له أفعالُ المعاصي.","en":"\"But as for he who withholds\", from what he was commanded, abandoning obligatory and recommended spending and whose soul was not generous in paying what is due to Allah, \"and considers himself free of need\", of Allah, leaving His worship aside and not seeing himself in utmost need of his Lord, with whom alone are its salvation, triumph and success, by His being its beloved and the one worshipped, to whom it turns, \"and denies the best\", that is, what Allah made it obligatory for servants to believe of good beliefs, \"We will ease him toward difficulty\", that is, toward the hard state and blameworthy traits, being eased toward evil wherever he is and assigned acts of disobedience."}},{"id":"kanz","ch":"iktinaz","t":"يأكلون أموال الناس بالباطل والذين يكنزون الذهب والفضة","r":[9,34,35],"n":"تحذّر الآيتان من أكل أموال الناس بالباطل ومن الذين يكنزون الذهب والفضة ولا ينفقونها في سبيل الله بعذاب أليم يوم تحمى عليها في نار جهنم.","wd":0,"q":{"w":"السعدي","bk":"saadi","s":9,"ay":34,"x":"{والذين يكنِزون الذَّهب والفضَّة}؛ أي: يمسكونهما، {ولا يُنفقونها في سبيل الله}؛ أي: طرق الخير الموصلة إلى الله، وهذا هو الكنز المحرَّم: أن يمسِكَها عن النفقة الواجبة، كأن يمنع منها الزكاة أو النفقات الواجبة للزوجات أو الأقارب أو النفقة في سبيل الله إذا وجبت؛ {فبشِّرۡهم بعذابٍ أليم}.","en":"\"And those who hoard gold and silver\", that is, hold them back, \"and do not spend them in the way of Allah\", that is, the paths of good that lead to Allah. This is the forbidden hoarding: to withhold them from obligatory spending, such as withholding zakat, or the obligatory maintenance of wives or relatives, or spending in the way of Allah when it becomes obligatory; \"then give them tidings of a painful punishment\"."}},{"id":"humaza","ch":"iktinaz","t":"الذي جمع مالاً وعدده يحسب أن ماله أخلده","r":[104,1,4],"n":"تصف الآيات الهمزة اللمزة بأنه جمع مالاً وعدّده ويظن أن ماله يخلده، وتتوعده بأن ينبذ في الحطمة.","wd":0,"q":{"w":"السعدي","bk":"saadi","s":104,"ay":2,"x":"ومن صفة هذا الهمَّازِ [اللَّمَّازِ] أنَّه لا همَّ له سوى جمع المال وتعديده والغبطة به، وليس له رغبةٌ في إنفاقه في طرق الخيرات وصلة الأرحام ونحو ذلك.","en":"Among the qualities of this slanderer is that he has no concern except gathering wealth, counting it and delighting in it, and has no desire to spend it on the paths of good, on joining kinship and the like."}},{"id":"takathur","ch":"iktinaz","t":"ألهاكم التكاثر حتى زرتم المقابر","r":[102,1,8],"n":"توبّخ الآيات من شغلهم التكاثر حتى زاروا المقابر، وتؤكد أنهم سيعلمون، وأنهم يُسألون يومئذ عن النعيم.","wd":0,"q":{"w":"السعدي","bk":"saadi","s":102,"ay":1,"x":"يقول تعالى موبِّخاً عباده عن اشتغالهم عمَّا خُلِقوا له من عبادته وحده لا شريك له ومعرفته والإنابة إليه وتقديم محبَّته على كلِّ شيءٍ: {ألۡهاكُمُ}: عن ذلك المذكور، {التَّكاثُرُ}: ولم يذكر المُتَكاثَرَ به؛ ليشمل ذلك كلَّ ما يَتَكاثَرُ به المتكاثرون ويفتخر به المفتخرون؛ من [التكاثر في] الأموال والأولاد والأنصار والجُنود والخدم والجاه وغير ذلك ممَّا يقصد منه مكاثرة كلِّ واحدٍ للآخر، وليس المقصود منه وجه الله.","en":"The Exalted says, rebuking His servants for being busy with other than what they were created for, His worship alone without partner, knowing Him, turning to Him and putting love of Him before everything: \"Diverted you\", from that mentioned, \"has competition in increase\", without mentioning what they compete in, so as to include everything in which competitors compete and boasters boast, of [competition in] wealth, children, supporters, soldiers, servants, rank and other things in which each seeks to outdo the other, and for which the face of Allah is not the aim."}},{"id":"turath","ch":"iktinaz","t":"وتأكلون التراث أكلاً لماً وتحبون المال حباً جماً","r":[89,17,20],"n":"تعدد الآيات من أحوال من لا يكرمون اليتيم ولا يحاضون على طعام المسكين ويأكلون التراث أكلاً لماً ويحبون المال حباً جماً.","wd":0,"q":{"w":"السعدي","bk":"saadi","s":89,"ay":17,"x":"ولهذا قال:{وتأكُلون التُّراثَ}؛ أي: المال المخلَّف، {أكلاً لَمًّا}؛ أي: ذريعاً، لا تبقون على شيء منه، {وتحبُّون المال حُبًّا جَمًّا}؛ أي: شديداً ، وهذا كقوله:{بل تؤثرون الحياةَ الدُّنيا والآخرةُ خيرٌ وأبقى}، {كلاَّ بل تحبُّونَ العاجِلَةَ وتَذَرون الآخرةَ}.","en":"Hence He said: \"And you consume inheritance, devouring [it] altogether\", that is, wholesale, leaving nothing of it, \"and you love wealth with immense love\", that is, intense; and this is like His words: \"But you prefer the worldly life, while the Hereafter is better and more lasting\", \"No! But you love the immediate and leave the Hereafter\"."}},{"id":"dabba","ch":"rizq","t":"وما من دابة في الأرض إلا على الله رزقها","r":[11,6,6],"n":"تقرر الآية أن رزق كل دابة في الأرض على الله، وأنه يعلم مستقرها ومستودعها.","wd":0,"q":{"w":"السعدي","bk":"saadi","s":11,"ay":6,"x":"أي: جميع ما دبَّ على وجه الأرض من آدميٍّ وحيوانٍ بَرِّيٍّ أو بحريٍّ؛ فالله تعالى قد تكفَّل بأرزاقهم وأقواتهم، فرزقُهم على الله. {ويعلم مستقرَّها ومستوۡدَعَها}؛ أي: يعلم مستقرَّ هذه الدوابِّ، وهو المكان الذي تقيم فيه وتستقرُّ فيه وتأوي إليه، ومستودعُها المكانُ الذي تنتقل إليه في ذهابها ومجيئها وعوارض أحوالها.","en":"That is, all that crawls on the face of the earth, human, land or sea animal: Allah has taken on Himself their provision and sustenance, so their provision is upon Allah. \"And He knows its place of dwelling and place of deposit\", that is, He knows the dwelling place of these creatures, where they stay, settle and take shelter, and their place of deposit, where they move in their coming and going and in the accidents of their conditions."}},{"id":"sama","ch":"rizq","t":"وفي السماء رزقكم وما توعدون","r":[51,22,23],"n":"تذكر الآية أن في السماء رزق الناس وما يوعدون، وتقسم الآية التي بعدها برب السماء والأرض على أنه حق.","wd":0,"q":{"w":"السعدي","bk":"saadi","s":51,"ay":22,"x":"وقوله: {وفي السماء رزقُكُم}؛ أي: مادة رزقكم من الأمطار وصنوف الأقدار؛ الرزق الدينيُّ والدنيويُّ، وما توعدونه من الجزاء في الدنيا والآخرة؛ فإنَّه ينزل من عند الله كسائر الأقدار.","en":"His words \"And in the heaven is your provision\", that is, the source of your provision from rains and kinds of decrees, religious and worldly provision, and what you are promised of recompense in this world and the next; for it descends from Allah like all decrees."}},{"id":"yughni","ch":"rizq","t":"إن يكونوا فقراء يغنهم الله من فضله","r":[24,32,32],"n":"تعد الآية الفقراء الراغبين في الزواج بأن يغنيهم الله من فضله، وتختم بأن الله واسع عليم.","wd":0,"q":{"w":"السعدي","bk":"saadi","s":24,"ay":32,"x":"وقوله:{إن يكونوا فقراءَ}؛ أي: الأزواج والمتزوِّجين، {يُغۡنِهِمُ الله من فضلِهِ}: فلا يمنعكم ما تتوهَّمون من أنَّه إذا تزوَّج افتقر بسبب كَثْرَةِ العائلة ونحوه. وفيه حثٌّ على التزوُّج ووعدٌ للمتزوِّج بالغنى بعد الفقر.","en":"His words \"If they should be poor\", that is, the spouses and those who marry, \"Allah will enrich them from His bounty\": so do not let what you imagine, that if he marries he becomes poor because of a large family and the like, hold you back. In it is an encouragement to marry and a promise to the one who marries of wealth after poverty."}},{"id":"yabsut","ch":"rizq","t":"ولو بسط الله الرزق لعباده لبغوا في الأرض","r":[42,27,27],"n":"تبين الآية أن بسط الرزق لعباده كلهم لأدّى إلى البغي في الأرض، وأنه ينزل بقدر ما يشاء إنه بعباده خبير بصير.","wd":0,"q":{"w":"السعدي","bk":"saadi","s":42,"ay":27,"x":"ثم ذكر أن من لطفِهِ بعبادِهِ أنَّه لا يوسِّع عليهم الدُّنيا سعةً تضرُّ بأديانهم، فقال:{ولو بَسَطَ الله الرزقَ لعبادِهِ لَبَغَوۡا في الأرض}؛ أي: لغفلوا عن طاعة الله، وأقبلوا على التمتُّع بشهوات الدُّنيا، فأوجبت لهم الإكباب على ما تشتهيه نفوسُهم، ولو كان معصيةً وظلماً. {ولكن يُنَزِّلُ بَقَدَرٍ ما يشاءُ}: بحسب ما اقتضاه لطفُه وحكمتُه، {إنَّه بعباده خبيرٌ بصيرٌ}: كما في بعض الآثار أنَّ الله تعالى يقول: «إنَّ مِنْ عبادي من لا يُصْلِحُ إيمانَه إلاّ الغنى، ولو أفقرتُه؛ لأفسده ذلك …","en":"Then He mentioned that part of His kindness to His servants is that He does not widen this world for them with a breadth that harms their religion, so He said: \"And if Allah had extended provision to His servants, they would have committed tyranny throughout the land\", that is, they would have been heedless of obeying Allah and turned to enjoying worldly desires, which would have caused them to devote themselves to what their souls desire, even if it were disobedience and injustice. \"But He sends down in due measure what He wills\", according to what His kindness and wisdom require; \"Indeed He is, of His servants, Aware and Seeing\": as in some reports that Allah, the Exalted, says: \"Among My servants are those whose faith is set right only by wealth, and were I to make him poor, that would corrupt it …"}},{"id":"wad","ch":"rizq","t":"الشيطان يعدكم الفقر ويأمركم بالفحشاء","r":[2,268,268],"n":"تقابل الآية بين وعد الشيطان بالفقر وأمره بالفحشاء، ووعد الله بالمغفرة والفضل.","wd":0,"q":{"w":"السعدي","bk":"saadi","s":2,"ay":268,"x":"فلما حثهم على الإنفاق النافع نهاهم عن الإمساك الضار، وبين لهم أنهم بين داعيين: داعي الرحمن يدعوهم إلى الخير ويعدهم عليه الخير والفضل والثواب العاجل والآجل وإخلاف ما أنفقوا، وداعي الشيطان الذي يحثهم على الإمساك، ويخوفهم إن أنفقوا أن يفتقروا.","en":"When He had urged them to beneficial spending, He forbade them harmful withholding and showed that they are between two callers: the caller of the Most Merciful, who calls them to good and promises them good, bounty, reward in this world and the next and replacement of what they spent; and the caller of Satan, who urges them to withhold and frightens them that if they spend they will become poor."}},{"id":"qarun","ch":"namadhij","t":"إنما أوتيته على علم عندي","r":[28,76,78],"n":"تعرض الآيات قارون وقد آتاه الله كنوزاً تنوء مفاتحها بالعصبة، ونصيحة قومه له، وجوابه أنه أوتيها على علم عنده.","wd":0,"q":{"w":"السعدي","bk":"saadi","s":28,"ay":78,"x":"فَـ {قَالَ} قارونُ رادًّا لنصيحتِهِم كافراً لنعمةِ ربِّه: {إنَّما أوتيتُهُ على علم عندي}؛ أي: إنَّما أدركتُ هذه الأموالَ بكسبي ومعرفتي بوجوه المكاسب وحِذْقي. أو: على علم من اللهِ بحالي؛ يعلمُ أنِّي أهلٌ لذلك؛ فلم تنصحوني على ما أعطاني الله؟! قال تعالى مبيِّناً أنَّ عطاءَه ليس دليلاً على حسنِ حالةِ المُعْطَى:{أوَلَمۡ يعلمۡ أنَّ الله قد أهۡلَكَ من قبلِهِ من القرونِ مَنۡ هو أشدُّ منه قوَّةً وأكثرُ جمعاً}: فما المانعُ من إهلاك قارون مع مضيِّ عادتِنا وسنَّتِنا بإهلاك مَن هُو مثلُه وأعظمُ منه إذا فَعَلَ ما يوجِب الهلاك؟!","en":"So Qarun said, rejecting their advice and being ungrateful for his Lord's blessing: \"I was only given it because of knowledge I have\", that is: I gained this wealth only through my earning, my knowledge of the ways of earning and my skill. Or: through knowledge from Allah of my state, that He knows I am deserving of it; so why do you advise me about what Allah gave me?! The Exalted said, showing that His giving is not proof of the good state of the one given: \"Did he not know that Allah had destroyed before him of generations those who were greater than him in power and greater in accumulation?\": what prevents Qarun's destruction, given our custom and way of destroying those like him and greater than him when he does what necessitates destruction?!"}},{"id":"jannatayn","ch":"namadhij","t":"واضرب لهم مثلاً رجلين جعلنا لأحدهما جنتين","r":[18,32,35],"n":"تضرب الآيات مثلاً برجلين لأحدهما جنتان من أعناب، فقال لصاحبه وهو يحاوره إنه أكثر مالاً وأعز نفراً، ودخل جنته وهو ظالم لنفسه.","wd":0,"q":{"w":"السعدي","bk":"saadi","s":18,"ay":32,"x":"فأحدُ هذين الرجلين الكافر لنعمة الله الجليلة جعل الله له جنتين؛ أي: بستانَيْنِ حسنَيْنِ {من أعناب وحفَفۡناهما بنخل}؛ أي: في هاتين الجنتين من كل الثمرات، وخصوصاً أشرف الأشجار العنب والنخل؛ فالعنب وسطها، والنخل قد حفَّ بذلك ودار به، فحصل فيه من حسن المنظر وبهائه وبروز الشجر والنخل للشمس والرياح التي تكمُلُ بها الثمار وتنضج وتتجوهر، ومع ذلك جعل بين تلك الأشجار زَرْعاً.","en":"One of these two men, the one ungrateful for the great blessing of Allah, Allah gave two gardens, that is, two fine orchards \"of grapevines, and We had surrounded them with palm trees\", that is, in these two gardens were all kinds of fruits, especially the noblest trees, grape and palm: the grape in the middle, and the palm surrounding and encircling it, so that it had beauty of sight and splendour, with the trees and palms exposed to the sun and winds by which fruit is perfected, ripened and matured; and moreover He placed crops between those trees."}}],"ay":{"22":"أُوْلَٰٓئِكَ ٱلَّذِينَ ٱشۡتَرَوُاْ ٱلضَّلَٰلَةَ بِٱلۡهُدَىٰ فَمَا رَبِحَت تِّجَٰرَتُهُمۡ وَمَا كَانُواْ مُهۡتَدِينَ","174":"يَٰٓأَيُّهَا ٱلنَّاسُ كُلُواْ مِمَّا فِي ٱلۡأَرۡضِ حَلَٰلٗا طَيِّبٗا وَلَا تَتَّبِعُواْ خُطُوَٰتِ ٱلشَّيۡطَٰنِۚ إِنَّهُۥ لَكُمۡ عَدُوّٞ مُّبِينٌ","251":"مَّن ذَا ٱلَّذِي يُقۡرِضُ ٱللَّهَ قَرۡضًا حَسَنٗا فَيُضَٰعِفَهُۥ لَهُۥٓ أَضۡعَافٗا كَثِيرَةٗۚ وَٱللَّهُ يَقۡبِضُ وَيَبۡصُۜطُ وَإِلَيۡهِ تُرۡجَعُونَ","270":"يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تُبۡطِلُواْ صَدَقَٰتِكُم بِٱلۡمَنِّ وَٱلۡأَذَىٰ كَٱلَّذِي يُنفِقُ مَالَهُۥ رِئَآءَ ٱلنَّاسِ وَلَا يُؤۡمِنُ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِۖ فَمَثَلُهُۥ كَمَثَلِ صَفۡوَانٍ عَلَيۡهِ تُرَابٞ فَأَصَابَهُۥ وَابِلٞ فَتَرَكَهُۥ صَلۡدٗاۖ لَّا يَقۡدِرُونَ عَلَىٰ شَيۡءٖ مِّمَّا كَسَبُواْۗ وَٱللَّهُ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلۡكَٰفِرِينَ","274":"ٱلشَّيۡطَٰنُ يَعِدُكُمُ ٱلۡفَقۡرَ وَيَأۡمُرُكُم بِٱلۡفَحۡشَآءِۖ وَٱللَّهُ يَعِدُكُم مَّغۡفِرَةٗ مِّنۡهُ وَفَضۡلٗاۗ وَٱللَّهُ وَٰسِعٌ عَلِيمٞ","279":"لِلۡفُقَرَآءِ ٱلَّذِينَ أُحۡصِرُواْ فِي سَبِيلِ ٱللَّهِ لَا يَسۡتَطِيعُونَ ضَرۡبٗا فِي ٱلۡأَرۡضِ يَحۡسَبُهُمُ ٱلۡجَاهِلُ أَغۡنِيَآءَ مِنَ ٱلتَّعَفُّفِ تَعۡرِفُهُم بِسِيمَٰهُمۡ لَا يَسۡـَٔلُونَ ٱلنَّاسَ إِلۡحَافٗاۗ وَمَا تُنفِقُواْ مِنۡ خَيۡرٖ فَإِنَّ ٱللَّهَ بِهِۦ عَلِيمٌ","280":"ٱلَّذِينَ يُنفِقُونَ أَمۡوَٰلَهُم بِٱلَّيۡلِ وَٱلنَّهَارِ سِرّٗا وَعَلَانِيَةٗ فَلَهُمۡ أَجۡرُهُمۡ عِندَ رَبِّهِمۡ وَلَا خَوۡفٌ عَلَيۡهِمۡ وَلَا هُمۡ يَحۡزَنُونَ","306":"زُيِّنَ لِلنَّاسِ حُبُّ ٱلشَّهَوَٰتِ مِنَ ٱلنِّسَآءِ وَٱلۡبَنِينَ وَٱلۡقَنَٰطِيرِ ٱلۡمُقَنطَرَةِ مِنَ ٱلذَّهَبِ وَٱلۡفِضَّةِ وَٱلۡخَيۡلِ ٱلۡمُسَوَّمَةِ وَٱلۡأَنۡعَٰمِ وَٱلۡحَرۡثِۗ ذَٰلِكَ مَتَٰعُ ٱلۡحَيَوٰةِ ٱلدُّنۡيَاۖ وَٱللَّهُ عِندَهُۥ حُسۡنُ ٱلۡمَـَٔابِ","307":"۞ قُلۡ أَؤُنَبِّئُكُم بِخَيۡرٖ مِّن ذَٰلِكُمۡۖ لِلَّذِينَ ٱتَّقَوۡاْ عِندَ رَبِّهِمۡ جَنَّٰتٞ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَا وَأَزۡوَٰجٞ مُّطَهَّرَةٞ وَرِضۡوَٰنٞ مِّنَ ٱللَّهِۗ وَٱللَّهُ بَصِيرُۢ بِٱلۡعِبَادِ","384":"لَن تَنَالُواْ ٱلۡبِرَّ حَتَّىٰ تُنفِقُواْ مِمَّا تُحِبُّونَۚ وَمَا تُنفِقُواْ مِن شَيۡءٖ فَإِنَّ ٱللَّهَ بِهِۦ عَلِيمٞ","472":"وَلَا يَحۡسَبَنَّ ٱلَّذِينَ يَبۡخَلُونَ بِمَآ ءَاتَىٰهُمُ ٱللَّهُ مِن فَضۡلِهِۦ هُوَ خَيۡرٗا لَّهُمۖ بَلۡ هُوَ شَرّٞ لَّهُمۡۖ سَيُطَوَّقُونَ مَا بَخِلُواْ بِهِۦ يَوۡمَ ٱلۡقِيَٰمَةِۗ وَلِلَّهِ مِيرَٰثُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۗ وَٱللَّهُ بِمَا تَعۡمَلُونَ خَبِيرٞ","984":"۞ يَٰبَنِيٓ ءَادَمَ خُذُواْ زِينَتَكُمۡ عِندَ كُلِّ مَسۡجِدٖ وَكُلُواْ وَٱشۡرَبُواْ وَلَا تُسۡرِفُوٓاْۚ إِنَّهُۥ لَا يُحِبُّ ٱلۡمُسۡرِفِينَ","1187":"وَٱعۡلَمُوٓاْ أَنَّمَآ أَمۡوَٰلُكُمۡ وَأَوۡلَٰدُكُمۡ فِتۡنَةٞ وَأَنَّ ٱللَّهَ عِندَهُۥٓ أَجۡرٌ عَظِيمٞ","1268":"۞ يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِنَّ كَثِيرٗا مِّنَ ٱلۡأَحۡبَارِ وَٱلرُّهۡبَانِ لَيَأۡكُلُونَ أَمۡوَٰلَ ٱلنَّاسِ بِٱلۡبَٰطِلِ وَيَصُدُّونَ عَن سَبِيلِ ٱللَّهِۗ وَٱلَّذِينَ يَكۡنِزُونَ ٱلذَّهَبَ وَٱلۡفِضَّةَ وَلَا يُنفِقُونَهَا فِي سَبِيلِ ٱللَّهِ فَبَشِّرۡهُم بِعَذَابٍ أَلِيمٖ","1269":"يَوۡمَ يُحۡمَىٰ عَلَيۡهَا فِي نَارِ جَهَنَّمَ فَتُكۡوَىٰ بِهَا جِبَاهُهُمۡ وَجُنُوبُهُمۡ وَظُهُورُهُمۡۖ هَٰذَا مَا كَنَزۡتُمۡ لِأَنفُسِكُمۡ فَذُوقُواْ مَا كُنتُمۡ تَكۡنِزُونَ","1337":"خُذۡ مِنۡ أَمۡوَٰلِهِمۡ صَدَقَةٗ تُطَهِّرُهُمۡ وَتُزَكِّيهِم بِهَا وَصَلِّ عَلَيۡهِمۡۖ إِنَّ صَلَوٰتَكَ سَكَنٞ لَّهُمۡۗ وَٱللَّهُ سَمِيعٌ عَلِيمٌ","1345":"۞ إِنَّ ٱللَّهَ ٱشۡتَرَىٰ مِنَ ٱلۡمُؤۡمِنِينَ أَنفُسَهُمۡ وَأَمۡوَٰلَهُم بِأَنَّ لَهُمُ ٱلۡجَنَّةَۚ يُقَٰتِلُونَ فِي سَبِيلِ ٱللَّهِ فَيَقۡتُلُونَ وَيُقۡتَلُونَۖ وَعۡدًا عَلَيۡهِ حَقّٗا فِي ٱلتَّوۡرَىٰةِ وَٱلۡإِنجِيلِ وَٱلۡقُرۡءَانِۚ وَمَنۡ أَوۡفَىٰ بِعَهۡدِهِۦ مِنَ ٱللَّهِۚ فَٱسۡتَبۡشِرُواْ بِبَيۡعِكُمُ ٱلَّذِي بَايَعۡتُم بِهِۦۚ وَذَٰلِكَ هُوَ ٱلۡفَوۡزُ ٱلۡعَظِيمُ","1478":"۞ وَمَا مِن دَآبَّةٖ فِي ٱلۡأَرۡضِ إِلَّا عَلَى ٱللَّهِ رِزۡقُهَا وَيَعۡلَمُ مُسۡتَقَرَّهَا وَمُسۡتَوۡدَعَهَاۚ كُلّٞ فِي كِتَٰبٖ مُّبِينٖ","1557":"وَيَٰقَوۡمِ أَوۡفُواْ ٱلۡمِكۡيَالَ وَٱلۡمِيزَانَ بِٱلۡقِسۡطِۖ وَلَا تَبۡخَسُواْ ٱلنَّاسَ أَشۡيَآءَهُمۡ وَلَا تَعۡثَوۡاْ فِي ٱلۡأَرۡضِ مُفۡسِدِينَ","1558":"بَقِيَّتُ ٱللَّهِ خَيۡرٞ لَّكُمۡ إِن كُنتُم مُّؤۡمِنِينَۚ وَمَآ أَنَا۠ عَلَيۡكُم بِحَفِيظٖ","1559":"قَالُواْ يَٰشُعَيۡبُ أَصَلَوٰتُكَ تَأۡمُرُكَ أَن نَّتۡرُكَ مَا يَعۡبُدُ ءَابَآؤُنَآ أَوۡ أَن نَّفۡعَلَ فِيٓ أَمۡوَٰلِنَا مَا نَشَٰٓؤُاْۖ إِنَّكَ لَأَنتَ ٱلۡحَلِيمُ ٱلرَّشِيدُ","2054":"وَءَاتِ ذَا ٱلۡقُرۡبَىٰ حَقَّهُۥ وَٱلۡمِسۡكِينَ وَٱبۡنَ ٱلسَّبِيلِ وَلَا تُبَذِّرۡ تَبۡذِيرًا","2055":"إِنَّ ٱلۡمُبَذِّرِينَ كَانُوٓاْ إِخۡوَٰنَ ٱلشَّيَٰطِينِۖ وَكَانَ ٱلشَّيۡطَٰنُ لِرَبِّهِۦ كَفُورٗا","2057":"وَلَا تَجۡعَلۡ يَدَكَ مَغۡلُولَةً إِلَىٰ عُنُقِكَ وَلَا تَبۡسُطۡهَا كُلَّ ٱلۡبَسۡطِ فَتَقۡعُدَ مَلُومٗا مَّحۡسُورًا","2171":"۞ وَٱضۡرِبۡ لَهُم مَّثَلٗا رَّجُلَيۡنِ جَعَلۡنَا لِأَحَدِهِمَا جَنَّتَيۡنِ مِنۡ أَعۡنَٰبٖ وَحَفَفۡنَٰهُمَا بِنَخۡلٖ وَجَعَلۡنَا بَيۡنَهُمَا زَرۡعٗا","2172":"كِلۡتَا ٱلۡجَنَّتَيۡنِ ءَاتَتۡ أُكُلَهَا وَلَمۡ تَظۡلِم مِّنۡهُ شَيۡـٔٗاۚ وَفَجَّرۡنَا خِلَٰلَهُمَا نَهَرٗا","2173":"وَكَانَ لَهُۥ ثَمَرٞ فَقَالَ لِصَٰحِبِهِۦ وَهُوَ يُحَاوِرُهُۥٓ أَنَا۠ أَكۡثَرُ مِنكَ مَالٗا وَأَعَزُّ نَفَرٗا","2174":"وَدَخَلَ جَنَّتَهُۥ وَهُوَ ظَالِمٞ لِّنَفۡسِهِۦ قَالَ مَآ أَظُنُّ أَن تَبِيدَ هَٰذِهِۦٓ أَبَدٗا","2185":"ٱلۡمَالُ وَٱلۡبَنُونَ زِينَةُ ٱلۡحَيَوٰةِ ٱلدُّنۡيَاۖ وَٱلۡبَٰقِيَٰتُ ٱلصَّٰلِحَٰتُ خَيۡرٌ عِندَ رَبِّكَ ثَوَابٗا وَخَيۡرٌ أَمَلٗا","2822":"وَأَنكِحُواْ ٱلۡأَيَٰمَىٰ مِنكُمۡ وَٱلصَّٰلِحِينَ مِنۡ عِبَادِكُمۡ وَإِمَآئِكُمۡۚ إِن يَكُونُواْ فُقَرَآءَ يُغۡنِهِمُ ٱللَّهُ مِن فَضۡلِهِۦۗ وَٱللَّهُ وَٰسِعٌ عَلِيمٞ","2921":"وَٱلَّذِينَ إِذَآ أَنفَقُواْ لَمۡ يُسۡرِفُواْ وَلَمۡ يَقۡتُرُواْ وَكَانَ بَيۡنَ ذَٰلِكَ قَوَامٗا","3019":"يَوۡمَ لَا يَنفَعُ مَالٞ وَلَا بَنُونَ","3020":"إِلَّا مَنۡ أَتَى ٱللَّهَ بِقَلۡبٖ سَلِيمٖ","3327":"۞ إِنَّ قَٰرُونَ كَانَ مِن قَوۡمِ مُوسَىٰ فَبَغَىٰ عَلَيۡهِمۡۖ وَءَاتَيۡنَٰهُ مِنَ ٱلۡكُنُوزِ مَآ إِنَّ مَفَاتِحَهُۥ لَتَنُوٓأُ بِٱلۡعُصۡبَةِ أُوْلِي ٱلۡقُوَّةِ إِذۡ قَالَ لَهُۥ قَوۡمُهُۥ لَا تَفۡرَحۡۖ إِنَّ ٱللَّهَ لَا يُحِبُّ ٱلۡفَرِحِينَ","3328":"وَٱبۡتَغِ فِيمَآ ءَاتَىٰكَ ٱللَّهُ ٱلدَّارَ ٱلۡأٓخِرَةَۖ وَلَا تَنسَ نَصِيبَكَ مِنَ ٱلدُّنۡيَاۖ وَأَحۡسِن كَمَآ أَحۡسَنَ ٱللَّهُ إِلَيۡكَۖ وَلَا تَبۡغِ ٱلۡفَسَادَ فِي ٱلۡأَرۡضِۖ إِنَّ ٱللَّهَ لَا يُحِبُّ ٱلۡمُفۡسِدِينَ","3329":"قَالَ إِنَّمَآ أُوتِيتُهُۥ عَلَىٰ عِلۡمٍ عِندِيٓۚ أَوَلَمۡ يَعۡلَمۡ أَنَّ ٱللَّهَ قَدۡ أَهۡلَكَ مِن قَبۡلِهِۦ مِنَ ٱلۡقُرُونِ مَنۡ هُوَ أَشَدُّ مِنۡهُ قُوَّةٗ وَأَكۡثَرُ جَمۡعٗاۚ وَلَا يُسۡـَٔلُ عَن ذُنُوبِهِمُ ٱلۡمُجۡرِمُونَ","3642":"وَمَآ أَمۡوَٰلُكُمۡ وَلَآ أَوۡلَٰدُكُم بِٱلَّتِي تُقَرِّبُكُمۡ عِندَنَا زُلۡفَىٰٓ إِلَّا مَنۡ ءَامَنَ وَعَمِلَ صَٰلِحٗا فَأُوْلَٰٓئِكَ لَهُمۡ جَزَآءُ ٱلضِّعۡفِ بِمَا عَمِلُواْ وَهُمۡ فِي ٱلۡغُرُفَٰتِ ءَامِنُونَ","4298":"۞ وَلَوۡ بَسَطَ ٱللَّهُ ٱلرِّزۡقَ لِعِبَادِهِۦ لَبَغَوۡاْ فِي ٱلۡأَرۡضِ وَلَٰكِن يُنَزِّلُ بِقَدَرٖ مَّا يَشَآءُۚ إِنَّهُۥ بِعِبَادِهِۦ خَبِيرُۢ بَصِيرٞ","4693":"وَفِيٓ أَمۡوَٰلِهِمۡ حَقّٞ لِّلسَّآئِلِ وَٱلۡمَحۡرُومِ","4696":"وَفِي ٱلسَّمَآءِ رِزۡقُكُمۡ وَمَا تُوعَدُونَ","4697":"فَوَرَبِّ ٱلسَّمَآءِ وَٱلۡأَرۡضِ إِنَّهُۥ لَحَقّٞ مِّثۡلَ مَآ أَنَّكُمۡ تَنطِقُونَ","4907":"وَٱلسَّمَآءَ رَفَعَهَا وَوَضَعَ ٱلۡمِيزَانَ","4908":"أَلَّا تَطۡغَوۡاْ فِي ٱلۡمِيزَانِ","4909":"وَأَقِيمُواْ ٱلۡوَزۡنَ بِٱلۡقِسۡطِ وَلَا تُخۡسِرُواْ ٱلۡمِيزَانَ","5081":"ءَامِنُواْ بِٱللَّهِ وَرَسُولِهِۦ وَأَنفِقُواْ مِمَّا جَعَلَكُم مُّسۡتَخۡلَفِينَ فِيهِۖ فَٱلَّذِينَ ءَامَنُواْ مِنكُمۡ وَأَنفَقُواْ لَهُمۡ أَجۡرٞ كَبِيرٞ","5132":"مَّآ أَفَآءَ ٱللَّهُ عَلَىٰ رَسُولِهِۦ مِنۡ أَهۡلِ ٱلۡقُرَىٰ فَلِلَّهِ وَلِلرَّسُولِ وَلِذِي ٱلۡقُرۡبَىٰ وَٱلۡيَتَٰمَىٰ وَٱلۡمَسَٰكِينِ وَٱبۡنِ ٱلسَّبِيلِ كَيۡ لَا يَكُونَ دُولَةَۢ بَيۡنَ ٱلۡأَغۡنِيَآءِ مِنكُمۡۚ وَمَآ ءَاتَىٰكُمُ ٱلرَّسُولُ فَخُذُوهُ وَمَا نَهَىٰكُمۡ عَنۡهُ فَٱنتَهُواْۚ وَٱتَّقُواْ ٱللَّهَۖ إِنَّ ٱللَّهَ شَدِيدُ ٱلۡعِقَابِ","5172":"يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ هَلۡ أَدُلُّكُمۡ عَلَىٰ تِجَٰرَةٖ تُنجِيكُم مِّنۡ عَذَابٍ أَلِيمٖ","5173":"تُؤۡمِنُونَ بِٱللَّهِ وَرَسُولِهِۦ وَتُجَٰهِدُونَ فِي سَبِيلِ ٱللَّهِ بِأَمۡوَٰلِكُمۡ وَأَنفُسِكُمۡۚ ذَٰلِكُمۡ خَيۡرٞ لَّكُمۡ إِن كُنتُمۡ تَعۡلَمُونَ","5174":"يَغۡفِرۡ لَكُمۡ ذُنُوبَكُمۡ وَيُدۡخِلۡكُمۡ جَنَّٰتٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ وَمَسَٰكِنَ طَيِّبَةٗ فِي جَنَّٰتِ عَدۡنٖۚ ذَٰلِكَ ٱلۡفَوۡزُ ٱلۡعَظِيمُ","5186":"فَإِذَا قُضِيَتِ ٱلصَّلَوٰةُ فَٱنتَشِرُواْ فِي ٱلۡأَرۡضِ وَٱبۡتَغُواْ مِن فَضۡلِ ٱللَّهِ وَٱذۡكُرُواْ ٱللَّهَ كَثِيرٗا لَّعَلَّكُمۡ تُفۡلِحُونَ","5196":"يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تُلۡهِكُمۡ أَمۡوَٰلُكُمۡ وَلَآ أَوۡلَٰدُكُمۡ عَن ذِكۡرِ ٱللَّهِۚ وَمَن يَفۡعَلۡ ذَٰلِكَ فَأُوْلَٰٓئِكَ هُمُ ٱلۡخَٰسِرُونَ","5255":"هُوَ ٱلَّذِي جَعَلَ لَكُمُ ٱلۡأَرۡضَ ذَلُولٗا فَٱمۡشُواْ فِي مَنَاكِبِهَا وَكُلُواْ مِن رِّزۡقِهِۦۖ وَإِلَيۡهِ ٱلنُّشُورُ","5494":"۞ إِنَّ رَبَّكَ يَعۡلَمُ أَنَّكَ تَقُومُ أَدۡنَىٰ مِن ثُلُثَيِ ٱلَّيۡلِ وَنِصۡفَهُۥ وَثُلُثَهُۥ وَطَآئِفَةٞ مِّنَ ٱلَّذِينَ مَعَكَۚ وَٱللَّهُ يُقَدِّرُ ٱلَّيۡلَ وَٱلنَّهَارَۚ عَلِمَ أَن لَّن تُحۡصُوهُ فَتَابَ عَلَيۡكُمۡۖ فَٱقۡرَءُواْ مَا تَيَسَّرَ مِنَ ٱلۡقُرۡءَانِۚ عَلِمَ أَن سَيَكُونُ مِنكُم مَّرۡضَىٰ وَءَاخَرُونَ يَضۡرِبُونَ فِي ٱلۡأَرۡضِ يَبۡتَغُونَ مِن فَضۡلِ ٱللَّهِ وَءَاخَرُونَ يُقَٰتِلُونَ فِي سَبِيلِ ٱللَّهِۖ فَٱقۡرَءُواْ مَا تَيَسَّرَ مِنۡهُۚ وَأَقِيمُواْ ٱلصَّلَوٰةَ وَءَاتُواْ ٱلزَّكَوٰةَ وَأَقۡرِضُواْ ٱللَّهَ قَرۡضًا حَسَنٗاۚ وَمَا تُقَدِّمُواْ لِأَنفُسِكُم مِّنۡ خَيۡرٖ تَجِدُوهُ عِندَ ٱللَّهِ هُوَ خَيۡرٗا وَأَعۡظَمَ أَجۡرٗاۚ وَٱسۡتَغۡفِرُواْ ٱللَّهَۖ إِنَّ ٱللَّهَ غَفُورٞ رَّحِيمُۢ","5598":"وَيُطۡعِمُونَ ٱلطَّعَامَ عَلَىٰ حُبِّهِۦ مِسۡكِينٗا وَيَتِيمٗا وَأَسِيرًا","5599":"إِنَّمَا نُطۡعِمُكُمۡ لِوَجۡهِ ٱللَّهِ لَا نُرِيدُ مِنكُمۡ جَزَآءٗ وَلَا شُكُورًا","5600":"إِنَّا نَخَافُ مِن رَّبِّنَا يَوۡمًا عَبُوسٗا قَمۡطَرِيرٗا","5848":"وَيۡلٞ لِّلۡمُطَفِّفِينَ","5849":"ٱلَّذِينَ إِذَا ٱكۡتَالُواْ عَلَى ٱلنَّاسِ يَسۡتَوۡفُونَ","5850":"وَإِذَا كَالُوهُمۡ أَو وَّزَنُوهُمۡ يُخۡسِرُونَ","5851":"أَلَا يَظُنُّ أُوْلَٰٓئِكَ أَنَّهُم مَّبۡعُوثُونَ","5852":"لِيَوۡمٍ عَظِيمٖ","5853":"يَوۡمَ يَقُومُ ٱلنَّاسُ لِرَبِّ ٱلۡعَٰلَمِينَ","6009":"كـَلَّاۖ بَل لَّا تُكۡرِمُونَ ٱلۡيَتِيمَ","6010":"وَلَا تَحَٰٓضُّونَ عَلَىٰ طَعَامِ ٱلۡمِسۡكِينِ","6011":"وَتَأۡكُلُونَ ٱلتُّرَاثَ أَكۡلٗا لَّمّٗا","6012":"وَتُحِبُّونَ ٱلۡمَالَ حُبّٗا جَمّٗا","6065":"وَأَمَّا مَنۢ بَخِلَ وَٱسۡتَغۡنَىٰ","6066":"وَكَذَّبَ بِٱلۡحُسۡنَىٰ","6067":"فَسَنُيَسِّرُهُۥ لِلۡعُسۡرَىٰ","6068":"وَمَا يُغۡنِي عَنۡهُ مَالُهُۥٓ إِذَا تَرَدَّىٰٓ","6168":"أَلۡهَىٰكُمُ ٱلتَّكَاثُرُ","6169":"حَتَّىٰ زُرۡتُمُ ٱلۡمَقَابِرَ","6170":"كـَلَّا سَوۡفَ تَعۡلَمُونَ","6171":"ثُمَّ كـَلَّا سَوۡفَ تَعۡلَمُونَ","6172":"كـَلَّا لَوۡ تَعۡلَمُونَ عِلۡمَ ٱلۡيَقِينِ","6173":"لَتَرَوُنَّ ٱلۡجَحِيمَ","6174":"ثُمَّ لَتَرَوُنَّهَا عَيۡنَ ٱلۡيَقِينِ","6175":"ثُمَّ لَتُسۡـَٔلُنَّ يَوۡمَئِذٍ عَنِ ٱلنَّعِيمِ","6179":"وَيۡلٞ لِّكُلِّ هُمَزَةٖ لُّمَزَةٍ","6180":"ٱلَّذِي جَمَعَ مَالٗا وَعَدَّدَهُۥ","6181":"يَحۡسَبُ أَنَّ مَالَهُۥٓ أَخۡلَدَهُۥ","6182":"كـَلَّاۖ لَيُنۢبَذَنَّ فِي ٱلۡحُطَمَةِ"},"nay":83,"nwd":0};
